"""Data models for Gemma LLM proposer and structured migration proposals."""

from __future__ import annotations

from pydantic import BaseModel, ConfigDict, Field

from exitkit.ledger.models import Claim, Evidence, ModelInfo, ProposalKind


class MigrationProposal(BaseModel):
    """Structured proposal generated by Gemma for exiting an at-risk dependency."""

    model_config = ConfigDict(frozen=True, extra="forbid")

    target_dependency: str = Field(description="Name of the dependency being evaluated")
    proposed_package: str = Field(
        description="Name of the upgraded or replacement package, or empty if vendored/removed"
    )
    proposed_specifier: str = Field(
        description="Version specifier constraint, e.g. '>=3.1.4' or '>=4.0.0'"
    )
    kind: ProposalKind = Field(description="Strategy kind: UPGRADE, REPLACE, or REMOVE_OR_VENDOR")
    rationale: str = Field(
        description="Architectural rationale justifying why this proposal was selected over others"
    )
    migration_steps: list[str] = Field(
        description="Concrete code transformations and manifest adjustments"
    )
    confidence: float = Field(
        ge=0.0,
        le=1.0,
        description="Model self-assessed confidence score between 0.0 and 1.0",
    )
    expected_shim_needed: bool = Field(
        description="Whether a compatibility shim is necessary for API divergences"
    )
    shim_code: str | None = Field(
        default=None,
        description="Optional Python shim code snippet if needed",
    )


class ProposerResult(BaseModel):
    """Result of running the bounded proposer on a dependency."""

    model_config = ConfigDict(frozen=True, extra="forbid")

    target_dependency: str
    target_repo: str
    proposal: MigrationProposal
    claim: Claim
    evidence: Evidence
    model_info: ModelInfo
    run_dir: str
